package com.hostelhub.controller;
import com.hostelhub.model.Student; import com.hostelhub.repository.StudentRepository; import com.hostelhub.service.RealtimeEventService; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/students") public class StudentController{ private final StudentRepository repo; private final RealtimeEventService events; public StudentController(StudentRepository r,RealtimeEventService e){repo=r;events=e;} @GetMapping public List<Student> all(){return repo.findAll();} @PostMapping public Student add(@Valid @RequestBody Student s){Student x=repo.save(s);events.publish("student","New student registered: "+x.getName());return x;} @PatchMapping("/{id}") public Student update(@PathVariable Long id,@RequestBody Student x){Student s=repo.findById(id).orElseThrow(); if(x.getName()!=null)s.setName(x.getName()); if(x.getEmail()!=null)s.setEmail(x.getEmail()); if(x.getDepartment()!=null)s.setDepartment(x.getDepartment()); if(x.getYear()!=null)s.setYear(x.getYear()); return repo.save(s);}
 @PatchMapping("/{id}/fee") public Student fee(@PathVariable Long id,@RequestParam String status){Student s=repo.findById(id).orElseThrow();s.setFeeStatus(status.toUpperCase());s=repo.save(s);events.publish("payment","Fee status updated for "+s.getName());return s;} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);events.publish("student","Student record deleted");}}
